    init: function (el) {
  var N = 16, img = [], x, y;
  for (y = 0; y < N; y++) { img.push([]); for (x = 0; x < N; x++) {
    var v = 45; if (x >= 2 && x <= 7 && y >= 2 && y <= 7) v = 215;
    var dx = x - 11, dy = y - 9; if (dx * dx + dy * dy <= 10) v = 150;
    if (y === 13 && x >= 2 && x <= 13) v = 235;
    v += (((x * 37 + y * 61) % 11) - 5) * 1.2; img[y].push(v); } }
  var K = { blur: [[1,1,1],[1,1,1],[1,1,1]].map(function (r) { return r.map(function (q) { return q / 9; }); }),
    sharp: [[0,-1,0],[-1,5,-1],[0,-1,0]], sx: [[-1,0,1],[-2,0,2],[-1,0,1]], sy: [[-1,-2,-1],[0,0,0],[1,2,1]], lap: [[0,1,0],[1,-4,1],[0,1,0]] };
  var cl = function (q) { return Math.max(0, Math.min(N - 1, q)); };
  var conv = function (k, edge) { var o = []; for (var i = 0; i < N; i++) { o.push([]); for (var j = 0; j < N; j++) {
    var s = 0; for (var m = -1; m <= 1; m++) for (var n = -1; n <= 1; n++) s += img[cl(i + m)][cl(j + n)] * k[m + 1][n + 1];
    o[i].push(edge ? Math.abs(s) : s); } } return o; };
  el.querySelectorAll('[data-kimg]').forEach(function (g) {
    var name = g.getAttribute('data-kimg'), ox = +g.getAttribute('data-x'), oy = +g.getAttribute('data-y');
    var out = name === 'orig' ? img : conv(K[name], name === 'sx' || name === 'sy' || name === 'lap');
    var s = '';
    for (var i = 0; i < N; i++) for (var j = 0; j < N; j++) {
      var v = Math.round(Math.max(0, Math.min(255, out[i][j])));
      s += '<rect x="' + (ox + j * 7) + '" y="' + (oy + i * 7) + '" width="7" height="7" fill="rgb(' + v + ',' + v + ',' + v + ')"/>';
    }
    g.innerHTML = s;
  });
}
